<script setup lang="ts">import{Head,Link,router}from'@inertiajs/vue3';import{route}from'ziggy-js';import{usePermissions}from'../../composables/usePermissions';interface Consulta{id:string;cliente:string;vehiculo:string;estado:string;prioridad:string;simulada:boolean;createdAt:string}defineProps<{consultas:{data:Consulta[];prev_page_url:string|null;next_page_url:string|null}}>();const{can}=usePermissions();</script>
<template><Head title="Asistente IA"/><UDashboardPanel><template #header><UDashboardNavbar title="Asistente de diagnóstico inicial"><template #right><UButton v-if="can('ia.solicitar')" label="Nueva orientación" icon="i-lucide-sparkles" @click="router.visit(route('ia.create'))"/></template></UDashboardNavbar></template><template #body><UAlert title="Orientación, no diagnóstico" description="La IA nunca sustituye la revisión física ni la confirmación de un mecánico autorizado." color="warning" icon="i-lucide-triangle-alert"/><div class="grid gap-4 lg:grid-cols-2"><Link v-for="c in consultas.data" :key="c.id" :href="route('ia.show',c.id)"><UCard class="h-full"><div class="flex justify-between gap-3"><div><p class="font-semibold">{{c.vehiculo}}</p><p class="text-sm text-muted">{{c.cliente}}</p></div><UBadge :color="c.prioridad==='alta'||c.prioridad==='critica'?'error':'primary'">{{c.prioridad}}</UBadge></div><div class="mt-4 flex items-center justify-between text-sm"><span>{{new Date(c.createdAt).toLocaleString('es-CO')}}</span><div class="flex gap-2"><UBadge v-if="c.simulada" color="neutral" variant="subtle">Simulada</UBadge><UBadge variant="subtle">{{c.estado}}</UBadge></div></div></UCard></Link><UCard v-if="!consultas.data.length" class="lg:col-span-2"><p class="py-10 text-center text-muted">Aún no hay orientaciones generadas.</p></UCard></div><div class="flex justify-end gap-2"><UButton label="Anterior" color="neutral" variant="outline" :disabled="!consultas.prev_page_url" @click="consultas.prev_page_url&&router.visit(consultas.prev_page_url)"/><UButton label="Siguiente" color="neutral" variant="outline" :disabled="!consultas.next_page_url" @click="consultas.next_page_url&&router.visit(consultas.next_page_url)"/></div></template></UDashboardPanel></template>
